Here is your expense tracker for Oct 2026: add an item, set a monthly budget and see the total and category split update live. Entries stay only while this page is open, so nothing is saved after you close it.

```page
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>
body{font-family:Segoe UI,sans-serif;margin:0;padding:16px;background:#f6f7f9;color:#1d2330}
h1{font-size:18px;margin:0 0 12px}
.card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0001}
.row{display:flex;gap:8px;flex-wrap:wrap}
input,select,button{font:inherit;padding:8px;border:1px solid #ccd;border-radius:8px}
input{flex:1;min-width:90px}
button{background:#2f6f4f;color:#fff;border:0;cursor:pointer}
button.x{background:none;color:#b33;padding:2px 8px}
.big{font-size:24px;font-weight:600}
.bar{height:8px;background:#e6e9ee;border-radius:4px;overflow:hidden;margin:3px 0 8px}
.bar i{display:block;height:100%;background:#2f6f4f}
.li{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
.sub{color:#667;font-size:12px}
.over{color:#b33}
</style></head><body>
<h1>Expenses: Oct 2026</h1>

<div class="card">
  <div class="row">
    <input id="d" placeholder="What for?">
    <input id="a" type="number" min="0" placeholder="Amount (₹)">
    <select id="c">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Other</option>
    </select>
    <button onclick="add()">Add</button>
  </div>
</div>

<div class="card">
  <div class="sub">Total spent</div>
  <div class="big" id="t">₹0</div>
  <div class="row" style="margin-top:8px;align-items:center">
    <span class="sub">Monthly budget (₹)</span>
    <input id="b" type="number" min="0" value="50000" oninput="draw()">
  </div>
  <div class="bar"><i id="bb" style="width:0"></i></div>
  <div id="left" class="sub"></div>
</div>

<div class="card"><div class="sub" style="margin-bottom:6px">By category</div><div id="cats"></div></div>

<div class="card"><div class="sub">Entries</div><div id="list"><div class="sub">Nothing added yet.</div></div></div>

<script>
var items=[];
function f(n){return '₹'+Math.round(n).toLocaleString('en-IN')}
function add(){
  var d=document.getElementById('d'),a=document.getElementById('a'),c=document.getElementById('c');
  var v=parseFloat(a.value);
  if(!(v>0))return;
  items.push({d:d.value.trim()||c.value,a:v,c:c.value});
  d.value='';a.value='';draw();
}
function del(i){items.splice(i,1);draw()}
function draw(){
  var tot=0,by={};
  items.forEach(function(x){tot+=x.a;by[x.c]=(by[x.c]||0)+x.a});
  document.getElementById('t').textContent=f(tot);
  var b=parseFloat(document.getElementById('b').value)||0;
  var pct=b>0?Math.min(100,tot/b*100):0;
  var bb=document.getElementById('bb');bb.style.width=pct+'%';
  bb.style.background=tot>b&&b>0?'#b33':'#2f6f4f';
  var l=document.getElementById('left');
  if(b>0){
    l.textContent=tot>b?'Over budget by '+f(tot-b):f(b-tot)+' left of '+f(b);
    l.className=tot>b?'sub over':'sub';
  } else l.textContent='';
  var h='';
  Object.keys(by).sort(function(x,y){return by[y]-by[x]}).forEach(function(k){
    h+='<div class="li" style="border:0;padding:0"><span>'+k+'</span><span>'+f(by[k])+'</span></div>'+
       '<div class="bar"><i style="width:'+(by[k]/tot*100)+'%"></i></div>';
  });
  document.getElementById('cats').innerHTML=h||'<div class="sub">No data yet.</div>';
  var s='';
  items.forEach(function(x,i){
    s='<div class="li"><span>'+esc(x.d)+' <span class="sub">'+x.c+'</span></span><span>'+f(x.a)+
      ' <button class="x" onclick="del('+i+')">✕</button></span></div>'+s;
  });
  document.getElementById('list').innerHTML=s||'<div class="sub">Nothing added yet.</div>';
}
function esc(t){return t.replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})}
draw();
</script>
</body></html>
```
